//! Entries slice 18 — Batch 207 (2026-10-07, Plan 207): the 10-07 staged
//! leads' `rust_perf` half — one cubecl IR-pass data-structure rule and one
//! bevy inlining rule.
//!
//! Two `rust_perf` rules distilled from `tracel-ai/cubecl` @ `d307dd46`
//! (#1767, MIT OR Apache-2.0) and `bevyengine/bevy` @ `1ba0c9f93969ff5a07a7a1ca3dc5168be03ef63e`
//! (#26040, MIT OR Apache-2.0). Quotes re-verified VERBATIM at the pins this
//! batch. Both `NotBenchable` on this box: the corpus harness benches Rust
//! micro-shapes, and both rules are decision-content (a scope-size crossover
//! and an inlining-propagation hazard) whose source measurements are
//! foreign-box laptop figures — provenance, never bars.

use crate::domains::rust_perf::PerfRule;

/// Data table, not logic — grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<PerfRule> {
    vec![
        // ── complexity: a scope-keyed table scanned linearly on EVERY lookup
        // and insert is quadratic in a region's operations — but the pure fix
        // (hash every scope) LOST 15% on small scopes at the source, so the
        // adopted shape is the HYBRID: inline-scan the first 8 entries
        // without allocating, hash past them ──────────────────────────────
        // Source: tracel-ai/cubecl #1767 (crates/cubecl-opt/src/scoped_map.rs
        // SmallMap + crates/cubecl-opt/src/passes/simple_cse.rs
        // ExpressionKey).
        PerfRule {
            rule_id: "per-scope-map-scan-hash-crossover".to_string(),
            name: "a scope-keyed lookup table scanned linearly on every lookup AND insert is quadratic in the operations of a region — hash each scope to make it linear, but a hash table per scope costs more than the scan it replaces when most scopes hold a handful of entries (measured 15% slower at the source), so the adopted shape is the HYBRID: inline-scan the first eight entries without allocating and hash past them".to_string(),
            category: "complexity".to_string(),
            buggy_code: "// naive: a scope-keyed lookup table backed by a Vec per scope. Every\n// lookup AND every insert scans the scope linearly — insert re-scans to\n// dedupe by key before pushing, get re-scans innermost-out to find — so\n// a CSE-style consumer over N region operations is O(N^2) in the\n// operations of the region. A large unrolled kernel spends minutes in\n// the pass.\npub struct ScopedMap<K, V> {\n    scopes: Vec<Vec<(K, V)>>,\n}\n\nimpl<K: PartialEq, V> ScopedMap<K, V> {\n    pub fn new() -> Self {\n        Self { scopes: vec![Vec::new()] }\n    }\n\n    pub fn push_scope(&mut self) {\n        self.scopes.push(Vec::new());\n    }\n\n    pub fn pop_scope(&mut self) {\n        self.scopes.pop();\n    }\n\n    // insert: the dedupe scan is O(scope) per insert — every new\n    // expression pays for the whole scope it lands in.\n    pub fn insert(&mut self, key: K, value: V) {\n        let scope = self.scopes.last_mut().unwrap();\n        if let Some(slot) = scope.iter_mut().find(|(k, _)| *k == key) {\n            slot.1 = value;\n            return;\n        }\n        scope.push((key, value));\n    }\n\n    // get: innermost-out scan — O(total entries) per lookup.\n    pub fn get(&self, key: &K) -> Option<&V> {\n        for scope in self.scopes.iter().rev() {\n            if let Some((_, v)) = scope.iter().find(|(k, _)| k == key) {\n                return Some(v);\n            }\n        }\n        None\n    }\n}\n\n// consumer: a common-subexpression memo over unrolled straight-line ops\n// — one get AND one insert per operation, so N unique ops cost\n// N x O(N) get + N x O(N) insert = O(N^2). The pass is quadratic in\n// the operations of the region.\npub fn cse_memo(ops: &[String]) -> Vec<Option<usize>> {\n    let mut seen = ScopedMap::new();\n    let mut hits = Vec::with_capacity(ops.len());\n    for (i, expr) in ops.iter().enumerate() {\n        if let Some(&first) = seen.get(expr) {\n            hits.push(Some(first)); // re-occurrence: reuse the first id\n        } else {\n            seen.insert(expr.clone(), i);\n            hits.push(None);\n        }\n    }\n    hits\n}\n"
                .to_string(),
            fixed_code: "// optimized: the HYBRID — each scope is a SmallMap that scans its first\n// INLINE_ENTRIES entries inline WITHOUT allocating and hashes only past\n// them. Most regions are a handful of additions (the inline arm wins:\n// no table to build, no allocation, no hashing); unrolled-kernel scopes\n// (thousands of entries) hash, so the pass is linear in the operations\n// of a region. The crossover is MEASURED, not asserted: the source's\n// first fix hashed EVERY scope and ran 15% slower on small scopes.\nuse std::collections::HashMap;\nuse std::hash::Hash;\n\nconst INLINE_ENTRIES: usize = 8; // the measured crossover, not a guess\n\npub struct SmallMap<K, V, const N: usize> {\n    inline: Vec<(K, V)>, // kept <= N: scanned, never hashed\n    overflow: Option<HashMap<K, V>>, // created on the first spill past N\n}\n\nimpl<K: Eq + Hash, V, const N: usize> SmallMap<K, V, N> {\n    fn new() -> Self {\n        Self { inline: Vec::new(), overflow: None }\n    }\n\n    fn get(&self, key: &K) -> Option<&V> {\n        // inline arm: <= N entries, no allocation, no hashing\n        if let Some((_, v)) = self.inline.iter().find(|(k, _)| k == key) {\n            return Some(v);\n        }\n        // past the crossover: hash instead of scanning an unbounded Vec\n        self.overflow.as_ref().and_then(|m| m.get(key))\n    }\n\n    fn insert(&mut self, key: K, value: V) {\n        if let Some(slot) = self.inline.iter_mut().find(|(k, _)| *k == key) {\n            slot.1 = value;\n            return;\n        }\n        if self.inline.len() < N {\n            self.inline.push((key, value)); // no hash table until it pays\n        } else {\n            self.overflow.get_or_insert_with(HashMap::new).insert(key, value);\n        }\n    }\n}\n\npub struct ScopedMap<K, V> {\n    scopes: Vec<SmallMap<K, V, INLINE_ENTRIES>>,\n}\n\nimpl<K: Eq + Hash, V> ScopedMap<K, V> {\n    pub fn new() -> Self {\n        Self { scopes: vec![SmallMap::new()] }\n    }\n\n    pub fn push_scope(&mut self) {\n        self.scopes.push(SmallMap::new());\n    }\n\n    pub fn pop_scope(&mut self) {\n        self.scopes.pop();\n    }\n\n    pub fn insert(&mut self, key: K, value: V) {\n        self.scopes.last_mut().unwrap().insert(key, value);\n    }\n\n    pub fn get(&self, key: &K) -> Option<&V> {\n        for scope in self.scopes.iter().rev() {\n            if let Some(v) = scope.get(key) {\n                return Some(v);\n            }\n        }\n        None\n    }\n}\n\n// THE KEY-TYPE LAW: the key hashes every field EXCEPT the one that has\n// no Hash (attributes/metadata stay in Eq). In-source comment, verbatim:\n// `AttributeDict` has no `Hash`: keys differing only in attributes share\n// a bucket and the equality tells them apart. Sharing a bucket BY DESIGN\n// is what keeps HashMap legal without weakening the equality.\n#[derive(PartialEq)]\npub struct Metadata;\n\npub struct ExpressionKey {\n    op_id: u32,\n    operands: Vec<u32>,\n    result_types: Vec<u32>,\n    mem_value: Option<u64>,\n    attrs: Metadata, // NO Hash for this field — deliberate\n}\n\nimpl Hash for ExpressionKey {\n    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {\n        self.op_id.hash(state);\n        self.operands.hash(state);\n        self.result_types.hash(state);\n        self.mem_value.hash(state);\n        // attrs deliberately NOT hashed\n    }\n}\n\nimpl PartialEq for ExpressionKey {\n    fn eq(&self, other: &Self) -> bool {\n        self.op_id == other.op_id\n            && self.operands == other.operands\n            && self.result_types == other.result_types\n            && self.mem_value == other.mem_value\n            && self.attrs == other.attrs // Eq keeps the distinction\n    }\n}\n\nimpl Eq for ExpressionKey {}\n\n// the same consumer is now linear in the region's operations: each\n// insert/get scans <= 8 inline entries (or hashes once past the\n// crossover) — the minutes-long quadratic is gone.\npub fn cse_memo(ops: &[String]) -> Vec<Option<usize>> {\n    let mut seen = ScopedMap::new();\n    let mut hits = Vec::with_capacity(ops.len());\n    for (i, expr) in ops.iter().enumerate() {\n        if let Some(&first) = seen.get(expr) {\n            hits.push(Some(first));\n        } else {\n            seen.insert(expr.clone(), i);\n            hits.push(None);\n        }\n    }\n    hits\n}\n"
                .to_string(),
            context_notes: Some("Grade B+ — NotBenchable decision-content ON THIS BOX (the minutes-long and 15% figures are SOURCE-REPORTED on their IR-pass workloads — provenance, never bars; the decision content is the CROSSOVER LAW, measured BOTH directions in-source, which is exactly what a local microbench of the fixture shapes could not give). ⛔ THE DECISION CONTENT IS THE TWO-SIDED MEASUREMENT: the naive fixture is a Vec-per-scope ScopedMap scanned linearly on every lookup AND insert (a CSE consumer over N region ops is O(N^2)); the first fix — hash EVERY scope — REGRESSED small scopes 15%, verbatim: 'Most scopes hold a handful of expressions, where a hash table per scope costs more than the scan it replaces: many regions of a few additions ran 15% slower than main. SmallMap scans its first eight entries inline, without allocating, and hashes past them.' — a rule this shape MUST carry the negative arm or it reads as 'always hash'. THE QUADRATIC ARM VERBATIM: 'SimpleCSE kept the expressions it had seen in a ScopedMap backed by a Vec per scope, scanned linearly on every lookup and insert, so the pass was quadratic in the operations of a region. A large unrolled kernel spent minutes in it. Each scope is now a hash map, and ExpressionKey hashes everything but its attributes, which have no Hash and stay in the equality.' THE ADOPTED SHAPE (in-source facts): const INLINE_ENTRIES: usize = 8 (scoped_map.rs L6) with doc 'Most scopes stay under this many entries and are scanned inline; larger ones hash.'; pub struct ScopedMap<K, V> { scopes: Vec<SmallMap<K, V, INLINE_ENTRIES>> } (L11); the bound widened impl<K: PartialEq, V> → impl<K: Hash + Eq, V> (L28). KEY-TYPE CLAUSE (simple_cse.rs L47-52): the ExpressionKey Hash impl hashes op_id, operands, result_types, mem_value — and the in-source comment (L44-45), verbatim: '`AttributeDict` has no `Hash`: keys differing only in attributes share a bucket and the equality tells them apart.' — when the key carries a field with no Hash (attributes/metadata), hash everything BUT it and let Eq keep the distinction; keys differing only in that field share a bucket BY DESIGN. BEFORE-STATE CITED: the source's own old doc comment said 'for small sets linear lookup tends to be faster' — INLINE_ENTRIES = 8 is that intuition MEASURED and BOUNDED instead of asserted wholesale. KINSHIP (grep-verified in this corpus, do not double-count): bsearch-sorted-slice (entries_01) is linear-scan → binary-search over SORTED data — a search-ORDER decision over ONE array, vs a per-scope CONTAINER choice here (distinct axis); fallthrough-toggle-oracle (B186) + construction-identity-row-classes-replace-probe (B193, kernel_opt) are the measurement-honesty family — this rule's negative arm is their ethos (publish the arm the fix LOST); aa-control-prices-the-fidelity-instrument (B177) is the complexity-class annotation-row sibling. REGIME: scope-keyed/region-keyed memo tables (CSE, GVN, symbol tables) whose scope-size distribution is small-with-a-long-tail. ANTI-REGIME: a scope known ALWAYS-large (skip the inline arm, hash directly); a key type whose Hash is expensive relative to Eq on tiny sets (hashing costs more than the 8-entry scan — the crossover moves, re-measure before bounding). Fixtures ORIGINAL (the Vec-per-scope and hybrid shapes transcribed as plain-Rust stand-ins; the IR-pass context is not pasted). CITE: tracel-ai/cubecl @ d307dd46efbe80ae133d299eadd6f794e4c82b01 (#1767) -- crates/cubecl-opt/src/scoped_map.rs L3-11,25-45 (the SmallMap hybrid) + crates/cubecl-opt/src/passes/simple_cse.rs L44-52 (the attribute-less Hash key), MIT OR Apache-2.0. Batch 207 / Plan 207 / Research 242.".to_string()),
            // Not benchable on this box: the minutes-long and 15% figures
            // are SOURCE-REPORTED IR-pass workloads (provenance, never
            // bars) — the decision content is the crossover law, measured
            // both directions in-source.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
        // ── dispatch: an #[inline(always)] hint does NOT propagate through
        // an unmarked wrapper — the refactor that wrapped the marked
        // internal in unmarked forwarders regressed four transform
        // benchmarks +30-90 us each; the fix is the hint on the WRAPPERS,
        // 2 insertions ────────────────────────────────────────────────────
        // Source: bevyengine/bevy #26040 (crates/bevy_ecs/src/query/iter.rs).
        PerfRule {
            rule_id: "inline-hint-not-through-unmarked-wrapper".to_string(),
            name: "an `#[inline(always)]` hint does not propagate through an unmarked wrapper — a refactor that wraps a marked hot function in unmarked forwarding functions silently stops the inlining and regresses every hot path through it, so every wrapper in a marked call chain carries the hint (or the chain is measured before the refactor lands)".to_string(),
            category: "dispatch".to_string(),
            buggy_code: "// naive: the internal fetch is marked #[inline(always)], but a refactor\n// wrapped it in a forwarding function with NO attribute. The hint does\n// not propagate: the wrapper itself is not eligible, so the wrapper\n// stays a REAL call and every iteration of the hot loop pays a call\n// boundary the pre-refactor build did not have. Tests stay green — only\n// benchmarks saw this class (+30-90 us per row at the source, every row\n// measured).\n#[inline(always)]\nunsafe fn fetch_next_internal(cursor: &mut usize, len: usize) -> Option<usize> {\n    if *cursor < len {\n        let idx = *cursor;\n        *cursor += 1;\n        Some(idx)\n    } else {\n        None\n    }\n}\n\n// the wrapper the mechanical refactor added: forwards 1:1, carries NO\n// inline hint — this link breaks the chain.\nunsafe fn fetch_next(cursor: &mut usize, len: usize) -> Option<usize> {\n    fetch_next_internal(cursor, len)\n}\n\n// the hot loop: one wrapper call per item, each a real call (no\n// inlining through the unmarked hop).\npub fn run_fetch_loop(items: &[u8]) -> usize {\n    let mut cursor = 0usize;\n    let mut sum = 0usize;\n    while let Some(i) = unsafe { fetch_next(&mut cursor, items.len()) } {\n        sum += items[i] as usize;\n    }\n    sum\n}\n"
                .to_string(),
            fixed_code: "// optimized: the hint rides EVERY link of the chain — #[inline(always)]\n// on the internal AND on the wrappers. The source's fix was exactly 2\n// insertions (the two wrapper fns); the internal already carried the\n// hint. Marking the wrappers restored the pre-refactor numbers and beat\n// them on the last row (281.9 vs 303.4 us). The discipline: an inline\n// hint is PER-FUNCTION, never transitive — a mechanical refactor that\n// adds wrappers around a marked hot function needs the wrapper-attribute\n// audit AND a bench before/after, because tests cannot see this class.\n#[inline(always)]\nunsafe fn fetch_next_internal(cursor: &mut usize, len: usize) -> Option<usize> {\n    if *cursor < len {\n        let idx = *cursor;\n        *cursor += 1;\n        Some(idx)\n    } else {\n        None\n    }\n}\n\n#[inline(always)]\nunsafe fn fetch_next(cursor: &mut usize, len: usize) -> Option<usize> {\n    fetch_next_internal(cursor, len) // the hop is now inlined away\n}\n\npub fn run_fetch_loop(items: &[u8]) -> usize {\n    let mut cursor = 0usize;\n    let mut sum = 0usize;\n    while let Some(i) = unsafe { fetch_next(&mut cursor, items.len()) } {\n        sum += items[i] as usize;\n    }\n    sum\n}\n\n#[test]\nfn wrappers_forward_identically() {\n    let items = [7u8, 9, 11];\n    assert_eq!(run_fetch_loop(&items), 27); // the wrapper stays 1:1\n}\n"
                .to_string(),
            context_notes: Some("Grade B− — NotBenchable on this box (the four-row table is a foreign LAPTOP measurement — provenance, never bars; the decision content is the hint-PROPAGATION law + the audit discipline that catches the class). ⛔ THE CLASS, verbatim from the commit message: '#25200 added wrappers around `fetch_next_aliased_unchecked_internal`, which is marked as `#[inline(always)]`. The new wrappers aren't marked as `#[inline(always)]`, so the function stopped getting inlined.' Inline hints are PER-FUNCTION, never transitive: LLVM inlines the wrapper only if the WRAPPER itself is eligible (no hint / too large = a real call at the link), so a marked callee behind an unmarked wrapper is a silent OPT-OUT — a mechanical refactor that adds forwarding layers around a marked hot function regresses every hot path through it while every test stays green. THE MEASURED TABLE (commit message, laptop, μs — source-reported, provenance never a bar; the unmarked-wrapper refactor cost +30-90 μs on EVERY row and marking the two wrappers restores — and on the last row BEATS — the pre-refactor numbers; columns = before #25200 → main → this PR): propagate_parent_transforms/full_recompute_roots_changed 300.6 ± 18.5 → 389.8 ± 14.7 → 308.4 ± 21.3 | propagate_parent_transforms/full_recompute_leaves_changed 482.0 ± 11.5 → 575.7 ± 10.7 → 488.5 ± 8.5 | transform_pipeline/localized_updates_static_optimized 428.5 ± 12.6 → 516.1 ± 16.4 → 407.4 ± 17.0 | transform_pipeline/localized_updates_no_static_optimization 303.4 ± 10.1 → 395.9 ± 14.1 → 281.9 ± 14.2. THE FIX is 2 insertions: #[inline(always)] added to unsafe fn fetch_next_aliased_unchecked (crates/bevy_ecs/src/query/iter.rs, post-commit ~L1598) and unsafe fn fetch_next_back_aliased_unchecked (~L2213) — the WRAPPERS; the internal already carried it; fixes #25840, merged 2026-10-06. THE DISCIPLINE (the transferable half): hot-path refactors that add indirection need a wrapper-attribute audit + a bench before/after — this regression SHIPPED and lived until a benchmark caught it. PROVENANCE NOTE (verbatim): 'I used a LLM to find the cause of the regression. I then read the #25200 diff to verify its claims and ran the benchmarks.' — the author disclosed LLM-assisted root-cause finding with MANUAL diff verification + benchmark confirmation; the verification discipline is the model, not the tool. KINSHIP (grep-verified in this corpus, do not double-count): dyn-to-enum (entries_01, dispatch) is the same ELIGIBILITY logic — the compiler can only inline what is eligible at each link; an opaque trait object kills eligibility at the CALL, an unmarked wrapper kills it at the HOP — static-dispatch axis vs hint-propagation axis, compose rather than substitute; fallthrough-toggle-oracle (B186) is the benchmark-as-oracle ethos — ONLY the bench saw this regression, no test could; bsearch-sorted-slice (entries_01) was checked and DECLINED — a search-order decision over one array, no hint-propagation content. REGIME: marked hot functions behind forwarding shims (iterator fetch/deref ladders, adapter layers, newtype pass-throughs). ANTI-REGIME: wrappers with real bodies (the hint is a size claim — #[inline(always)] on a large body bloats; measure); #[inline] (the declinable hint is the wrong repair for a measured 30%-class regression). Fixtures ORIGINAL (safe stand-ins keeping the internal→wrapper→hot-loop shape; the bevy iterator machinery is not pasted). CITE: bevyengine/bevy @ 1ba0c9f93969ff5a07a7a1ca3dc5168be03ef63e (#26040) -- crates/bevy_ecs/src/query/iter.rs (the two #[inline(always)] insertions on the wrappers, post-commit ~L1598 + ~L2213) + the commit message (the cause + the four-row laptop table), MIT OR Apache-2.0. Batch 207 / Plan 207 / Research 242.".to_string()),
            // Not benchable on this box: the four-row table is a foreign
            // laptop measurement (provenance, never bars) — the decision
            // content is the per-function hint-propagation law + the
            // wrapper-attribute audit discipline.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
    ]
}
